#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals trigo. Require Import Reals. Set Implicit Arguments. Unset Strict Implicit.Unset Printing Implicit Defensive. Section triangle_tangent_15_16. Variable R : realType. Theorem triangle_tangent_15_16: exists A B C : R * R, let dist P Q := Num.sqrt ((fst P - fst Q)^+2 + (snd P - snd Q)^+2) in dist A C = 16 /\dist B C = 15 /\dist A B = sqrt 481 /\let u := (fst A - fst C, snd A - snd C) in let v := (fst B - fst C, snd B - snd C) in u.1*v.1+u.2*v.2=0 /\tan (angle u v) = 15/16. Proof. by []. Qed. End triangle_tangent_15_16.
